1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest case and base premiums ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("a single sword → base premium 100 G, plus 10 G first insurance and 5 G fee → 115 G");
15	  it.todo("a single amulet → base premium 60 G → premium 71 G");
16	  it.todo("a single staff → base premium 80 G → premium 93 G");
17	  it.todo("a single potion → base premium 40 G → premium 49 G");
18	
19	  // --- Components and the building block of 3 alike ---
20	  it.todo("1 rune → base premium 25 G");
21	  it.todo("2 runes → 50 G base premium (no block)");
22	  it.todo("3 runes → 60 G base premium (block applies)");
23	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
24	  it.todo("7 runes → 175 G base premium");
25	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
26	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
27	
28	  // --- Item-specific modifiers ---
29	  it.todo("cursed sword adds a 50 % surcharge on that item's base premium");
30	  it.todo("sword with exactly enchantment 5 → 30 % high-enchantment surcharge applies");
31	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
32	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
33	  it.todo(
34	    "policy with a cursed sword and a plain amulet → base 160 G, curse surcharge 50 G (item-scoped) → 210 G before further modifiers and fee",
35	  );
36	
37	  // --- Policy-wide modifiers ---
38	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
39	  it.todo("customer with 1 year → no loyalty discount");
40	  it.todo("each item in a quote carries the 10 % first insurance surcharge");
41	  it.todo("the second quote of a customer receives a 15 % follow-up contract discount");
42	  it.todo("a 5 G processing fee is added to every premium");
43	
44	  // --- Rounding ---
45	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
46	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
47	
48	  // --- Integration examples ---
49	  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
50	  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
51	
52	  // --- Claims: standard reimbursement ---
53	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
54	  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
55	
56	  // --- Claims: special clauses ---
57	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
58	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
59	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
60	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
61	
62	  // --- Claims: deductible per damage event ---
63	  it.todo("a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
64	
65	  // --- Claims: insurance sum and cap ---
66	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
67	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
68	  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
69	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
70	  it.todo("two successive claims of 1500 G on a sword → payout 1400 G (cap remaining 600 G), then payout 600 G (cap remaining 0 G)");
71	
72	  // --- Claims: multiple items of the same type ---
73	  it.todo("two sword damage entries against a policy covering two swords → each entry gets its own deductible");
74	
75	  // --- Errors ---
76	  it.todo("quote with an unknown item type (e.g. broomstick) → error");
77	  it.todo("claim referencing an item not part of the policy (amulet damaged when only a sword is insured) → error");
78	  it.todo("claim with more damage entries of a type than the policy covers → error");
79	  it.todo("claim with a damage entry with amount -200 → error");
80	
81	  // --- CLI ---
82	  it.todo("the CLI reads a scenario JSON from stdin and writes {\"results\": [...]} to stdout");
83	  it.todo("the CLI exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
84	});
